  text: '1309年から約70年間、フランス王の圧力で教皇庁がここに移されました。古代のユダヤ人のバビロン捕囚になぞらえて、「教皇のバビロン捕囚」と呼ばれます。そのあとの教会大分裂で、教皇の権威は大きく落ちました。'
