  text: '911年、ノルマン人の首長ロロがフランス王から与えられて公国をつくった土地です。1066年、ノルマンディー公ウィリアムがイングランドを征服しました。1944年6月6日には、連合軍がこの海岸に上陸しました（ノルマンディー上陸作戦）。'
