  text: '16世紀、ポルトガルのアジアの香辛料や南ドイツの銀が集まり、ヨーロッパ商業・金融の中心になりました。オランダ独立戦争中の1585年にスペイン軍に占領されると、商人たちはアムステルダムへ移り、繁栄の中心も移っていきました。',
