  text: 'バイエルンの中心都市です。1923年にヒトラーがここで一揆をおこして失敗し、1938年にはイギリス・フランスがチェコスロヴァキアのズデーテン地方をドイツにゆずるミュンヘン会談が開かれました（宥和政策）。'
