  text: 'バルト海沿岸の地方で、ドイツ騎士団が征服してドイツ人を移住させました。1525年にプロイセン公国となり、ブランデンブルク選帝侯の国と一体になって、1701年にプロイセン王国が成立しました。この国がのちのドイツ統一の中心になります。'
