  text: 'ドイツ騎士団が建設した町で、プロイセン公国の都、プロイセン王国発祥の地です。哲学者カントは、生涯この町からほとんど出なかったといわれます。第二次世界大戦後ソ連領になり、ソ連の政治家の名前にちなんで改名されました。',
