  text: 'ドナウ川沿いのローマ軍の基地から始まり、ハプスブルク家の都として中欧の中心になりました。1529年と1683年の2度、オスマン帝国の大軍に包囲されましたが持ちこたえました。ナポレオン戦争後には、ヨーロッパの秩序を話し合うウィーン会議が開かれました。',
