  text: 'ローマ人がテムズ川に橋をかけてつくった町ロンディニウムから始まりました。中世からイングランドの中心で、17世紀にはピューリタン革命・名誉革命の舞台になりました。19世紀には、世界の工場・世界の銀行であったイギリスの首都として、世界一の大都市になりました。',
  fun: '1851年のロンドン万国博覧会の会場は、鉄とガラスでつくられた巨大な「水晶宮（クリスタル=パレス）」です。600万人以上が見に来ました。'
